#!/usr/bin/env python3
"""Data-only code-reference proposals. No Source binding, core or cache mutation."""
from pathlib import Path
import json,hashlib,collections
ROOT=Path(__file__).resolve().parents[3];AUDIT=Path(__file__).resolve().parent;OUT=ROOT/'data/manifests/uncoded'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ledger=json.loads((AUDIT/'am-code-slot-ledger.json').read_text());reviews=json.loads((AUDIT/'am-code-visual-reviews.json').read_text());slots={x['slot_id']:x for x in ledger['slots']};by_source=collections.defaultdict(list)
 for r in reviews['records']:
  if r['visual_status']!='confirmed_primary_code_only':assert r['confirmed_code'] is None;continue
  slot=slots[r['slot_id']];crop=r['primary_crop'];assert sha(ROOT/crop['crop_png_path'])==crop['crop_png_sha256'];assert r['confirmed_code']==slot['confirmed_code']
  token=hashlib.sha256(json.dumps({'source':r['artifact_sha256'],'page':r['page'],'native_image_box':crop['embedded_image_crop_box']},sort_keys=True,separators=(',',':')).encode()).hexdigest()[:16];key=f'primary-code-p{r["page"]}-{token}';locator='primary-raster-code/'+key;code=r['confirmed_code']
  evidence={'source_id':r['source_id'],'artifact_sha256':r['artifact_sha256'],'page':r['page'],'printed_page':None,'section':'Literal code occurrence only; no body definition reviewed','excerpt':code,'bbox':crop['bbox_pdf_display'],'locator':locator,'method':'automated-primary-raster-code-visual-review-v1','primary_crop_png_path':crop['crop_png_path'],'primary_crop_png_sha256':crop['crop_png_sha256'],'primary_native_crop_pixel_sha256':crop['primary_native_crop_pixel_sha256'],'embedded_image_sha256':crop['embedded_image_sha256'],'embedded_image_xref':crop['image_xref'],'embedded_image_pixels':crop['embedded_image_pixels'],'embedded_image_crop_box':crop['embedded_image_crop_box'],'image_to_pdf_unit_transform':crop['image_to_pdf_unit_transform'],'lossless_reading_rotation_degrees':crop['lossless_reading_rotation_degrees'],'review_manifest_path':r['contact_manifest_path'],'review_manifest_sha256':r['contact_manifest_sha256'],'actor_type':'automated','actor_id':r['actor_id']}
  by_source[r['source_id']].append({'source_id':r['source_id'],'artifact_sha256':r['artifact_sha256'],'key':key,'parent_key':None,'code':code,'text':code,'kind':'referencia_no_documento','page':r['page'],'locator':locator,'positions':[],'evidence':[evidence],'source_context':{'slot_id':r['slot_id'],'raw_glyph_label':r['raw_glyph_label'],'primary_visual_notes':r['notes'],'body_not_verified':True,'definition_wording_not_asserted':True,'national_equivalence_not_asserted':True,'year_component_not_inferred_from_code':True,'OCR_hypotheses_not_evidence':slot['hypotheses_only']},'actor_type':'automated','actor_id':r['actor_id'],'pedagogical_review_status':'not_reviewed','technical_validation_status':'automated_primary_code_pixels_read_only','publication_status':'proposal_not_ingested','extraction_method':'automated-primary-raster-code-visual-review-v1'})
 results=[]
 for sid,items in sorted(by_source.items()):
  assert len({x['key'] for x in items})==len(items);source=next(s for s in ledger['sources'] if s['id']==sid);path=OUT/f'am-primary-code-references-{sid.removeprefix("am-rca-")}.json';wrapper={'source_id':sid,'artifact_sha256':source['sha256'],'actor_type':'automated','actor_id':'agent:rs_adapter:visual-primary-code-peer','contract_status':'data_only_proposal_not_bound_to_Source','requires_explicit_primary_raster_review_verifier':True,'scope':'Confirmed literal code-only documentary references. No definition wording/body, position, equivalence or source completeness asserted. Ambiguous slots remain in ledger with null code and are not emitted.','items':items};path.write_text(json.dumps(wrapper,ensure_ascii=False,indent=2)+'\n');results.append({'source_id':sid,'path':str(path.relative_to(ROOT)),'sha256':sha(path),'confirmed_code_only_records':len(items)})
 report={'actor_type':'automated','reviewed_slots':len(reviews['records']),'pending_slots':len(ledger['slots'])-len(reviews['records']),'review_statuses':reviews['counts'],'source_bindings_modified':False,'core_or_cache_modified':False,'publication_or_definition_verified':False,'outputs':results};(AUDIT/'am-primary-code-reference-proposal.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps(report,ensure_ascii=False))
if __name__=='__main__':main()
